#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <random>
#include <sstream>
#include <string>
#include <vector>

struct Count { int y, n, mult; };

static std::vector<Count> read_counts(const std::string& path) {
    std::ifstream in(path);
    if (!in) throw std::runtime_error("cannot open input");
    std::string line;
    std::getline(in, line);
    std::vector<std::pair<int,int>> raw;
    while (std::getline(in, line)) {
        if (line.empty()) continue;
        std::replace(line.begin(), line.end(), ',', ' ');
        std::istringstream ss(line);
        int y, n;
        if (!(ss >> y >> n)) throw std::runtime_error("bad input row");
        raw.push_back({y, n});
    }
    if (raw.size() != 71) throw std::runtime_error("expected 71 rows");
    std::vector<Count> out;
    for (const auto& r : raw) {
        auto it = std::find_if(out.begin(), out.end(), [&](const Count& c) {
            return c.y == r.first && c.n == r.second;
        });
        if (it == out.end()) out.push_back({r.first, r.second, 1});
        else ++it->mult;
    }
    return out;
}

static long double digamma(long double x) {
    long double result = 0.0L;
    while (x < 6.0L) {
        result -= 1.0L / x;
        x += 1.0L;
    }
    const long double xx = x * x;
    result += std::log(x) - 0.5L / x;
    result -= 1.0L / (12.0L * xx);
    result += 1.0L / (120.0L * xx * xx);
    result -= 1.0L / (252.0L * xx * xx * xx);
    result += 1.0L / (240.0L * xx * xx * xx * xx);
    result -= 1.0L / (132.0L * xx * xx * xx * xx * xx);
    return result;
}

static void analytic_part(const std::vector<Count>& counts,
                          const std::string& csv_path,
                          const std::string& json_path) {
    std::vector<long double> x, z;
    for (int i = 230; i >= 131; --i) x.push_back(i / 100.0L);
    for (int j = 100; j <= 499; ++j) z.push_back(j / 100.0L);

    std::vector<long double> logw(x.size() * z.size());
    long double maxlw = -std::numeric_limits<long double>::infinity();
    for (size_t ix = 0; ix < x.size(); ++ix) {
        const long double xv = x[ix];
        const long double ex = std::exp(xv);
        for (size_t iz = 0; iz < z.size(); ++iz) {
            const long double zv = z[iz];
            const long double s = std::exp(zv);
            const long double a = std::exp(xv + zv) / (1.0L + ex);
            const long double b = s / (1.0L + ex);
            long double lp = -2.5L * std::log(s) + std::log(a) + std::log(b);
            for (const Count& c : counts) {
                lp += static_cast<long double>(c.mult) *
                    (std::lgammal(s) + std::lgammal(a + c.y) +
                     std::lgammal(b + c.n - c.y) - std::lgammal(a) -
                     std::lgammal(b) - std::lgammal(s + c.n));
            }
            logw[ix * z.size() + iz] = lp;
            if (std::isfinite(lp) && lp > maxlw) maxlw = lp;
        }
    }
    if (!std::isfinite(maxlw)) throw std::runtime_error("non-finite analytic grid");

    std::vector<long double> w(logw.size());
    long double sum = 0.0L;
    for (size_t k = 0; k < logw.size(); ++k) {
        w[k] = std::exp(logw[k] - maxlw);
        sum += w[k];
    }
    for (long double& value : w) value /= sum;

    long double mean_a = 0.0L, mean_b = 0.0L;
    size_t mode_k = 0;
    for (size_t k = 0; k < w.size(); ++k) if (w[k] > w[mode_k]) mode_k = k;
    for (size_t ix = 0; ix < x.size(); ++ix) {
        const long double ex = std::exp(x[ix]);
        for (size_t iz = 0; iz < z.size(); ++iz) {
            const size_t k = ix * z.size() + iz;
            const long double s = std::exp(z[iz]);
            const long double a = std::exp(x[ix] + z[iz]) / (1.0L + ex);
            const long double b = s / (1.0L + ex);
            mean_a += a * w[k];
            mean_b += b * w[k];
        }
    }
    const size_t mode_ix = mode_k / z.size();
    const size_t mode_iz = mode_k % z.size();

    std::ofstream out(csv_path);
    if (!out) throw std::runtime_error("cannot write grid CSV");
    out << std::setprecision(17) << std::fixed;
    out << "X,Z,alpha,beta,normed_exp_trans\n";
    for (size_t ix = 0; ix < x.size(); ++ix) {
        const long double ex = std::exp(x[ix]);
        for (size_t iz = 0; iz < z.size(); ++iz) {
            const size_t k = ix * z.size() + iz;
            const long double s = std::exp(z[iz]);
            const long double a = std::exp(x[ix] + z[iz]) / (1.0L + ex);
            const long double b = s / (1.0L + ex);
            out << static_cast<double>(x[ix]) << ','
                << static_cast<double>(z[iz]) << ','
                << static_cast<double>(a) << ','
                << static_cast<double>(b) << ','
                << static_cast<double>(w[k]) << '\n';
        }
    }
    out.close();

    std::ofstream js(json_path);
    if (!js) throw std::runtime_error("cannot write analytic JSON");
    js << std::setprecision(17);
    js << "{\"mean_alpha\":" << static_cast<double>(mean_a)
       << ",\"mean_beta\":" << static_cast<double>(mean_b)
       << ",\"mode_x\":" << static_cast<double>(x[mode_ix])
       << ",\"mode_z\":" << static_cast<double>(z[mode_iz]) << "}\n";
}

static long double part2_logpost(const std::array<long double,2>& q,
                                 std::array<long double,2>& grad,
                                 const std::vector<Count>& counts) {
    constexpr long double huge = 100.0L;
    if (!std::isfinite(q[0]) || !std::isfinite(q[1]) ||
        q[0] < -huge || q[0] > huge || q[1] < -huge || q[1] > huge)
        return -std::numeric_limits<long double>::infinity();
    const long double a = std::exp(q[0]);
    const long double b = std::exp(q[1]);
    const long double s = a + b;
    long double lp = -a * a / 200.0L - b * b / 200.0L
                   - 2.5L * std::log(s) + std::log(a) + std::log(b);
    long double dla = 0.0L, dlb = 0.0L;
    for (const Count& c : counts) {
        const long double ds = digamma(s) - digamma(s + c.n);
        const long double mult = c.mult;
        lp += mult * (std::lgammal(s) + std::lgammal(a + c.y) +
                      std::lgammal(b + c.n - c.y) - std::lgammal(a) -
                      std::lgammal(b) - std::lgammal(s + c.n));
        dla += mult * (ds + digamma(a + c.y) - digamma(a));
        dlb += mult * (ds + digamma(b + c.n - c.y) - digamma(b));
    }
    // Derivatives with respect to log a and log b, including transformed-density Jacobian.
    const long double base_a = dla - a / 100.0L - 2.5L / s;
    const long double base_b = dlb - b / 100.0L - 2.5L / s;
    grad[0] = a * base_a + 1.0L;
    grad[1] = b * base_b + 1.0L;
    if (!std::isfinite(lp) || !std::isfinite(grad[0]) || !std::isfinite(grad[1]))
        return -std::numeric_limits<long double>::infinity();
    return lp;
}

static std::pair<double,double> run_chain(unsigned seed,
                                           const std::vector<Count>& counts,
                                           std::vector<double>* kept_a,
                                           std::vector<double>* kept_b) {
    std::mt19937_64 rng(seed);
    std::normal_distribution<double> normal(0.0, 1.0);
    std::uniform_int_distribution<int> steps_dist(1, 20);
    std::uniform_real_distribution<double> uniform01(0.0, 1.0);
    std::array<long double,2> q;
    q[0] = seed == 101 ? std::log(0.5L) : std::log(2.0L);
    q[1] = seed == 101 ? std::log(0.5L) : std::log(2.0L);
    std::array<long double,2> grad{};
    long double lp = part2_logpost(q, grad, counts);
    double epsilon = 0.05;
    double log_epsilon_bar = std::log(epsilon);
    long double hbar = 0.0L;
    const long double target = 0.95L;
    constexpr int warmup = 2000, retained = 2000;
    unsigned accepted_retained = 0;

    for (int iter = 0; iter < warmup + retained; ++iter) {
        std::array<long double,2> p{normal(rng), normal(rng)};
        std::array<long double,2> qprop = q, pprop = p;
        std::array<long double,2> gprop = grad;
        const int nsteps = steps_dist(rng);
        bool numerical_ok = true;
        for (int step = 0; step < nsteps; ++step) {
            for (int d = 0; d < 2; ++d) pprop[d] += 0.5L * epsilon * gprop[d];
            for (int d = 0; d < 2; ++d) qprop[d] += epsilon * pprop[d];
            long double newlp = part2_logpost(qprop, gprop, counts);
            if (!std::isfinite(newlp)) { numerical_ok = false; break; }
            for (int d = 0; d < 2; ++d) pprop[d] += 0.5L * epsilon * gprop[d];
        }
        long double accept_stat = 0.0L;
        if (numerical_ok) {
            const long double newlp = part2_logpost(qprop, gprop, counts);
            if (std::isfinite(newlp)) {
                const long double h0 = -lp + 0.5L * (p[0]*p[0] + p[1]*p[1]);
                const long double h1 = -newlp + 0.5L * (pprop[0]*pprop[0] + pprop[1]*pprop[1]);
                const long double ratio = h0 - h1;
                accept_stat = ratio < 0.0L ? std::exp(ratio) : 1.0L;
                if (uniform01(rng) < accept_stat) {
                    q = qprop;
                    lp = newlp;
                    grad = gprop;
                    if (iter >= warmup) ++accepted_retained;
                }
            }
        }
        if (iter < warmup) {
            const long double m = iter + 1.0L;
            const long double t0 = 10.0L;
            hbar = (1.0L - 1.0L / (m + t0)) * hbar +
                   (target - accept_stat) / (m + t0);
            const long double gamma = 0.05L, kappa = 0.75L;
            const long double log_eps = std::log(10.0L * epsilon) -
                                         std::sqrt(m) * hbar / gamma;
            epsilon = std::exp(log_eps);
            const long double eta = std::pow(m, -kappa);
            log_epsilon_bar = eta * log_eps + (1.0L - eta) * log_epsilon_bar;
            if (iter == warmup - 1) epsilon = std::exp(log_epsilon_bar);
            if (!std::isfinite(epsilon) || epsilon <= 0.0L || epsilon > 10.0L)
                epsilon = std::clamp(epsilon, 1e-6, 10.0);
        }
        if (iter >= warmup) {
            kept_a->push_back(static_cast<double>(std::exp(q[0])));
            kept_b->push_back(static_cast<double>(std::exp(q[1])));
        }
    }
    return {epsilon, static_cast<double>(accepted_retained) / retained};
}

static void mcmc_part(const std::vector<Count>& counts,
                      const std::string& json_path) {
    std::vector<double> a1, b1, a2, b2;
    auto r1 = run_chain(101, counts, &a1, &b1);
    auto r2 = run_chain(202, counts, &a2, &b2);
    if (a1.size() != 2000 || b1.size() != 2000 ||
        a2.size() != 2000 || b2.size() != 2000)
        throw std::runtime_error("wrong retained sample count");
    long double ma = 0.0L, mb = 0.0L;
    for (size_t i = 0; i < a1.size(); ++i) { ma += a1[i]; mb += b1[i]; }
    for (size_t i = 0; i < a2.size(); ++i) { ma += a2[i]; mb += b2[i]; }
    ma /= 4000.0L; mb /= 4000.0L;
    std::cerr << "HMC chain 1: step_size=" << r1.first
              << ", retained_acceptance=" << r1.second << "\n";
    std::cerr << "HMC chain 2: step_size=" << r2.first
              << ", retained_acceptance=" << r2.second << "\n";
    std::ofstream js(json_path);
    if (!js) throw std::runtime_error("cannot write MCMC JSON");
    js << std::setprecision(17);
    js << "{\"mean_alpha\":" << static_cast<double>(ma)
       << ",\"mean_beta\":" << static_cast<double>(mb)
       << ",\"n_chains\":2,\"draws_per_chain\":2000,\"target_accept\":0.95,"
       << "\"sampler\":\"adaptive Hamiltonian Monte Carlo (C++, leapfrog, dual-averaged step size)\"}\n";
}

int main() {
    try {
        std::vector<Count> counts = read_counts("inputs/rat_tumor_counts.csv");
        analytic_part(counts, "outputs/analytic_marginal_posterior_grid.csv",
                      "outputs/analytic_summary.json");
        mcmc_part(counts, "outputs/mcmc_posterior_means.json");
        std::cout << "completed\n";
    } catch (const std::exception& e) {
        std::cerr << "error: " << e.what() << "\n";
        return 1;
    }
}
