new=r'''static long double whitened_target(const std::array<long double,2>& r,
                                   std::array<long double,2>& grad,
                                   const std::vector<Count>& counts) {
    // Posterior covariance of (log a, log b), estimated from the same target.
    constexpr long double mean0 = 0.64601487676868752L;
    constexpr long double mean1 = 2.4195607805349524L;
    constexpr long double l00 = 0.27993031104491386L;
    constexpr long double l10 = 0.26164558296344318L;
    constexpr long double l11 = 0.11133458888456768L;
    std::array<long double,2> q{
        mean0 + l00 * r[0],
        mean1 + l10 * r[0] + l11 * r[1]
    };
    std::array<long double,2> gq{};
    const long double lp = part2_logpost(q, gq, counts);
    grad[0] = l00 * gq[0] + l10 * gq[1];
    grad[1] = l11 * gq[1];
    return lp;  // The constant log-Jacobian does not affect HMC.
}

static std::pair<double,double> run_chain(unsigned seed,
                                           const std::vector<Count>& counts,
                                           std::vector<double>* kept_a,
                                           std::vector<double>* kept_b) {
    std::mt19937_64 rng(seed);
    std::normal_distribution<double> normal(0.0, 1.0);
    std::uniform_int_distribution<int> steps_dist(5, 30);
    std::uniform_real_distribution<double> uniform01(0.0, 1.0);

    constexpr long double mean0 = 0.64601487676868752L;
    constexpr long double mean1 = 2.4195607805349524L;
    constexpr long double l00 = 0.27993031104491386L;
    constexpr long double l10 = 0.26164558296344318L;
    constexpr long double l11 = 0.11133458888456768L;

    // Mildly overdispersed starts in standardized coordinates.
    std::array<long double,2> r{
        seed == 101 ? -1.5L : 1.5L,
        seed == 101 ? 1.5L : -1.5L
    };
    std::array<long double,2> grad{};
    long double lp = whitened_target(r, grad, counts);
    double epsilon = 0.1;
    const double dual_mu = std::log(10.0 * epsilon);
    double log_epsilon_bar = dual_mu;
    long double hbar = 0.0L;
    constexpr long double target = 0.95L;
    constexpr int warmup = 2000, retained = 2000;
    unsigned accepted_retained = 0;

    for (int iter = 0; iter < warmup + retained; ++iter) {
        std::array<long double,2> p{normal(rng), normal(rng)};
        std::array<long double,2> rprop = r, pprop = p, gprop = grad;
        const int nsteps = steps_dist(rng);
        bool numerical_ok = true;
        for (int step = 0; step < nsteps; ++step) {
            for (int d = 0; d < 2; ++d) pprop[d] -= 0.5L * epsilon * gprop[d];
            for (int d = 0; d < 2; ++d) rprop[d] += epsilon * pprop[d];
            const long double newlp = whitened_target(rprop, gprop, counts);
            if (!std::isfinite(newlp)) { numerical_ok = false; break; }
            for (int d = 0; d < 2; ++d) pprop[d] -= 0.5L * epsilon * gprop[d];
        }
        long double accept_stat = 0.0L;
        if (numerical_ok) {
            const long double newlp = whitened_target(rprop, gprop, counts);
            if (std::isfinite(newlp)) {
                const long double h0 = -lp + 0.5L * (p[0]*p[0] + p[1]*p[1]);
                const long double h1 = -newlp + 0.5L * (pprop[0]*pprop[0] + pprop[1]*pprop[1]);
                const long double ratio = h0 - h1;
                accept_stat = ratio < 0.0L ? std::exp(ratio) : 1.0L;
                if (uniform01(rng) < accept_stat) {
                    r = rprop;
                    lp = newlp;
                    grad = gprop;
                    if (iter >= warmup) ++accepted_retained;
                }
            }
        }
        if (iter < warmup) {
            const long double m = iter + 1.0L;
            const long double t0 = 10.0L;
            hbar = (1.0L - 1.0L / (m + t0)) * hbar +
                   (target - accept_stat) / (m + t0);
            const long double gamma = 0.05L, kappa = 0.75L;
            const long double log_eps = dual_mu - std::sqrt(m) * hbar / gamma;
            epsilon = std::exp(log_eps);
            const long double eta = std::pow(m, -kappa);
            log_epsilon_bar = eta * log_eps + (1.0L - eta) * log_epsilon_bar;
            if (iter == warmup - 1) epsilon = std::exp(log_epsilon_bar);
            if (!std::isfinite(epsilon) || epsilon <= 0.0L)
                epsilon = 1e-6;
            epsilon = std::min(epsilon, 10.0);
        }
        if (iter >= warmup) {
            const long double loga = mean0 + l00 * r[0];
            const long double logb = mean1 + l10 * r[0] + l11 * r[1];
            kept_a->push_back(static_cast<double>(std::exp(loga)));
            kept_b->push_back(static_cast<double>(std::exp(logb)));
        }
    }
    return {epsilon, static_cast<double>(accepted_retained) / retained};
}

